import pathlib, unittest, subprocess, shutil
ROOT=pathlib.Path(__file__).resolve().parents[1]
class TouchscreenReturnContract(unittest.TestCase):
 def test_return_requires_scan_availability_review_batch_and_status_only_recovery(self):
  s=(ROOT/'kiosk/return-ui.js').read_text()
  for token in ["request('/scan'",'candidate && candidate.id !== root.id','already in the batch','/return/availability?ids=','Recorded condition:','Return location:','Required note if condition changed','Optional return note','at most 50 distinct items','Confirm return',"request('/operation/status'",'state.uncertain = true','session_generation: captured.generation','session_instance: captured.instance',"'X-Homebox-Client': window.touchscreenClientId"]:
   self.assertIn(token,s)
  self.assertNotIn('anonymous_return',s)
  self.assertIn("await request('/api/kit?id=' + encodeURIComponent(root.id))",s)
  self.assertIn("condition.setAttribute('aria-label'",s)
  self.assertIn('min-height:48px', (ROOT/'kiosk/touchscreen.css').read_text())
  self.assertIn('state.reviewed = false; scan.value',s)
 def test_html_and_shell_mount_return_flow(self):
  html=(ROOT/'kiosk/touchscreen.html').read_text();shell=(ROOT/'kiosk/touchscreen.js').read_text();server=(ROOT/'deploy/kiosk-server.py').read_text()
  self.assertIn('/return-ui.js',html);self.assertIn("window.beginReturn?.()",shell);self.assertIn("'/return-ui.js':'return-ui.js'",server)
 def test_current_return_ui_browser_behavior(self):
  node=shutil.which('node')
  if not node:self.skipTest('Node unavailable')
  source=(ROOT/'kiosk/return-ui.js').read_text()
  fixture=r'''global.window={checkoutSession:{generation:null,instance:null},listeners:{},addEventListener(k,f){(this.listeners[k]??=[]).push(f)},dispatchEvent(e){for(const f of this.listeners[e.type]||[])f(e)}};
global.crypto={randomUUID(){return 'request-key'}};global.localStorage={getItem(){return 'client-uuid'}};global.Event=class{constructor(type){this.type=type}};global.CustomEvent=class extends Event{constructor(type,o){super(type);this.detail=o?.detail}};
class N{constructor(tag){this.tag=tag;this.children=[];this.handlers={};this.textContent='';this.value='';this.placeholder='';this.disabled=false}append(...v){this.children.push(...v)}replaceChildren(...v){this.children=v}addEventListener(k,f){this.handlers[k]=f}setAttribute(k,v){this[k]=v}focus(){} }
global.Option=class extends N{constructor(text,value){super('option');this.textContent=text;this.value=value}};const host=new N('section');global.document={querySelector(){return host},createElement(t){return new N(t)}};
let calls=[],confirmCount=0,statusCount=0,done=null,availabilityCount=0,verifiedIds=new Set();window.touchscreenClientId='client-uuid';window.addEventListener('ccrate-flow-done',e=>done=e.detail);
global.fetch=async(path,opt={})=>{calls.push([path,opt]);if(path==='/api/inventory')return response([{id:'asset-id',name:'Asset'}]);if(path==='/scan'){const code=JSON.parse(opt.body).code;const id=code==='wrong'?'wrong-id':code==='kitcode'?'kit-id':code==='partcode'?'component-id':code==='second'?'second-id':'asset-id';verifiedIds.add(id);return response({entity:{id,name:id==='kit-id'?'Kit':id==='component-id'?'Component':id==='asset-id'?'Asset':'Asset two',...(id==='kit-id'?{customFields:[{name:'Equipment kit manifest',value:'{\"version\":1}'}]}:{})}})}if(path.startsWith('/api/kit'))return response(path.includes('kit-id')?{kit:true,entities:[{id:'kit-id',name:'Kit'},{id:'component-id',name:'Component'}],versions:{'kit-id':'v1'},verified:[...verifiedIds]}:{kit:false});if(path.startsWith('/return/availability')){const ids=decodeURIComponent(path.split('ids=')[1]).split(',');const eligible=++availabilityCount>1;return response({items:ids.map(id=>({id,eligible,reason:eligible?null: 'Assigned item is not checked out',condition:'Ready',location:{id:'loc',name:'Bench'}}))})}if(path==='/return/confirm'){confirmCount++;throw Error('response lost')}if(path==='/operation/status'){statusCount++;return response({status:'completed',id:'receipt',count:1})}throw Error('unexpected '+path)};function response(data){return {ok:true,json:async()=>data}}function all(n){return [n,...n.children.flatMap(all)]}function find(text){return all(host).find(n=>n.textContent===text)}function input(ph){return all(host).find(n=>n.placeholder===ph)}
'''+source+r'''
;(async()=>{await window.beginReturn();if(!all(host).some(n=>n.textContent.includes('Scan your member badge first.')))throw Error('badge gate absent');window.checkoutSession={generation:5,instance:'session-A'};window.dispatchEvent(new Event('ccrate-session-change'));await window.beginReturn();const q=input('Search by name or ID');q.value='Asset';await q.handlers.input();const choice=find('Asset');await choice.handlers.click();let scan=input('Scan item barcode');scan.value='wrong';await find('Verify scan and add').handlers.click();if(!all(host).some(n=>n.textContent.includes('does not match selected candidate')))throw Error('candidate mismatch not rejected');scan.value='match';await find('Verify scan and add').handlers.click();if(!all(host).some(n=>n.textContent.includes('Assigned item is not checked out')))throw Error('blocked availability reason not shown');scan.value='match';await find('Verify scan and add').handlers.click();if(!all(host).some(n=>n.textContent.includes('Bench')&&n.textContent.includes('Ready')))throw Error('condition/location not shown');scan=input('Scan item barcode');scan.value='kitcode';await find('Verify scan and add').handlers.click();if(!all(host).some(n=>n.textContent.includes('Scan kit component')))throw Error('incomplete native kit did not request a component scan');scan=input('Scan item barcode');scan.value='partcode';await find('Verify scan and add').handlers.click();scan=input('Scan item barcode');scan.value='kitcode';await find('Verify scan and add').handlers.click();if(!calls.some(x=>x[0].startsWith('/api/kit'))||!all(host).some(n=>n.textContent.includes('Kit manifest: Kit, Component'))||all(host).filter(n=>n.tag==='article').length!==2)throw Error('native kit component was not folded into its root');const sel=all(host).find(n=>n.tag==='select');sel.value='Broken';await sel.handlers.change();const issue=input('Required note if condition changed');issue.value='Cracked';await issue.handlers.input();const retNote=input('Optional return note');retNote.value='On lower shelf';await retNote.handlers.input();await find('Review return').handlers.click();scan=input('Scan item barcode');scan.value='second';await find('Verify scan and add').handlers.click();if(!find('Confirm return').disabled)throw Error('adding a return item did not invalidate review');await find('Review return').handlers.click();await find('Confirm return').handlers.click();if(confirmCount!==1||!find('Check saved result'))throw Error('uncertain confirmation not recoverable');await find('Check saved result').handlers.click();if(statusCount!==1||confirmCount!==1||!find('Return complete'))throw Error('status recovery retried confirmation');find('Done').handlers.click();if(done?.generation!==5||done?.instance!=='session-A')throw Error('Done lost captured session '+JSON.stringify(done));for(const [path,opt] of calls.filter(x=>['/scan','/return/confirm','/operation/status'].includes(x[0])||x[0].startsWith('/api/kit')||x[0].startsWith('/return/availability')))if(opt.headers?.['X-Homebox-Client']!=='client-uuid')throw Error('missing client header for '+path);const payload=JSON.parse(calls.find(x=>x[0]==='/return/confirm')[1].body);const target=payload.targets[0];if(new Set(payload.targets.map(x=>x.entity_id)).size!==payload.targets.length||payload.targets.length!==4||target.condition!=='Broken'||target.note!=='Cracked'||target.return_note!=='On lower shelf'||!payload.request_key||payload.kit_versions['kit-id']!=='v1')throw Error('return fields were not preserved')})().catch(e=>{console.error(e);process.exitCode=1});'''
  result=subprocess.run([node,'-e',fixture],cwd=ROOT,capture_output=True,text=True)
  self.assertEqual(result.returncode,0,result.stderr)
 def test_server_ended_member_session_preserves_return_receipt_until_done(self):
  s=(ROOT/'kiosk/return-ui.js').read_text()
  listener=s[s.index("window.addEventListener('ccrate-session-change'"):]
  self.assertIn('if (state.preserved && sameSession(captured))',listener)
  shell=(ROOT/'kiosk/touchscreen.js').read_text()
  self.assertIn("Boolean(window.returnReceiptPreserved&&state.flow==='return'&&!authenticated)",shell)
  self.assertIn('generation:authenticated?gen:null',shell)
 def test_late_scan_from_member_a_cannot_add_to_member_b_batch(self):
  node=shutil.which('node')
  if not node:self.skipTest('Node unavailable')
  source=(ROOT/'kiosk/return-ui.js').read_text()
  fixture=r'''global.window={checkoutSession:{generation:1,instance:'A',authenticated:true},touchscreenClientId:'stable-client',listeners:{},addEventListener(k,f){(this.listeners[k]??=[]).push(f)},dispatchEvent(e){for(const f of this.listeners[e.type]||[])f(e)}};
global.localStorage={getItem(){return 'stable-client'}};global.crypto={randomUUID(){return 'request-key'}};global.Event=class{constructor(type){this.type=type}};global.CustomEvent=class extends Event{constructor(type,o){super(type);this.detail=o?.detail}};
class N{constructor(tag){this.tag=tag;this.children=[];this.handlers={};this.textContent='';this.value='';this.placeholder='';this.disabled=false}append(...v){this.children.push(...v)}replaceChildren(...v){this.children=v}addEventListener(k,f){this.handlers[k]=f}setAttribute(k,v){this[k]=v}focus(){}}
global.Option=class extends N{constructor(text,value){super('option');this.textContent=text;this.value=value}};const host=new N('section');global.document={querySelector(){return host},createElement(t){return new N(t)}};
let finishScan,calls=[];global.fetch=(path,opt={})=>{calls.push(path);if(path==='/scan')return new Promise(resolve=>{finishScan=()=>resolve({ok:true,json:async()=>({entity:{id:'late-asset',name:'Late asset'}})});});throw Error('Unexpected request '+path)};
function all(n){return [n,...n.children.flatMap(all)]}function find(text){return all(host).find(n=>n.textContent===text)}
'''+source+r'''
;(async()=>{await window.beginReturn();const scan=all(host).find(n=>n.placeholder==='Scan item barcode');scan.value='A scan';const pending=find('Verify scan and add').handlers.click();window.checkoutSession={generation:2,instance:'B',authenticated:true};window.dispatchEvent(new Event('ccrate-session-change'));finishScan();await pending;if(all(host).some(n=>n.tag==='article')||calls.some(path=>path.startsWith('/api/kit')))throw Error('late response from member A mutated member B return state');if(!all(host).some(n=>n.placeholder==='Scan item barcode'))throw Error('member B return UI was not available after the stale request');})().catch(e=>{console.error(e);process.exitCode=1});'''
  result=subprocess.run([node,'-e',fixture],cwd=ROOT,capture_output=True,text=True)
  self.assertEqual(result.returncode,0,result.stderr)

if __name__=='__main__':unittest.main()
